{
  "name": "Ondax SureLock VHG稳频激光二极管模块",
  "name_en": "Ondax SureLock VHG-stabilized laser diode module",
  "manufacturer": "Ondax",
  "description": "这是一款采用体全息光栅（VHG）稳频的半导体激光模块，可调节激光二极管电流、温度和光功率，并控制激光发射启停。它通常作为实验室中的稳定激光光源，用于光谱测量及其他光学实验。",
  "description_en": "A VHG-stabilized semiconductor laser module with adjustable laser diode current, temperature, and optical power, plus control of laser emission enable/disable state. It is typically used as a stable laboratory laser source for spectroscopy and other optical experiments.",
  "tag_hints": [
    "laser diode module",
    "VHG-stabilized laser",
    "optical power control",
    "laser current control",
    "diode temperature control",
    "spectroscopy",
    "lab laser source"
  ],
  "actions": [
    {
      "action_name": "auto-current",
      "description": "获取/设置激光二极管电流",
      "description_en": "get/set laser diode current"
    },
    {
      "action_name": "auto-enabled",
      "description": "获取/设置激光发射启用状态",
      "description_en": "get/set laser emission enabled state"
    },
    {
      "action_name": "auto-maximum_current",
      "description": "获取/设置激光二极管最大电流限制",
      "description_en": "get/set maximum laser diode current limit"
    },
    {
      "action_name": "auto-power",
      "description": "获取/设置激光光功率",
      "description_en": "get/set laser optical power"
    },
    {
      "action_name": "auto-reset",
      "description": "重置激光控制器",
      "description_en": "reset the laser controller"
    },
    {
      "action_name": "auto-save",
      "description": "将当前设置保存到闪存",
      "description_en": "save current settings to flash memory"
    },
    {
      "action_name": "auto-temperature",
      "description": "获取/设置激光二极管温度",
      "description_en": "get/set laser diode temperature"
    },
    {
      "action_name": "auto-firmware",
      "description": "获取固件版本",
      "description_en": "get firmware version"
    },
    {
      "action_name": "auto-serial_number",
      "description": "获取控制器序列号",
      "description_en": "get controller serial number"
    },
    {
      "action_name": "auto-status",
      "description": "获取激光控制器运行状态",
      "description_en": "get laser controller run status"
    },
    {
      "action_name": "auto-target",
      "description": "设定目标设定值",
      "description_en": "define target setpoint"
    },
    {
      "action_name": "auto-on",
      "description": "打开激光发射",
      "description_en": "turn laser emission on"
    },
    {
      "action_name": "auto-off",
      "description": "关闭激光发射",
      "description_en": "turn laser emission off"
    },
    {
      "action_name": "auto-on_time",
      "description": "设定开启时长参数",
      "description_en": "define on-time duration parameter"
    },
    {
      "action_name": "auto-off_time",
      "description": "设定关闭时长参数",
      "description_en": "define off-time duration parameter"
    }
  ]
}

